-- ShowcaseBuilder: builds Workspace.AssetShowcase, a labelled walk-through of every model.
-- GENERATED by tools/roblox/gen_showcase.py from game/manifest.json + game/asset_ids.json.
-- Paste the whole file into the Studio command bar in EDIT mode (not Play) and press Enter.
-- Safe to re-run: it deletes and rebuilds Workspace.AssetShowcase and touches nothing else.

local DATA = __DATA__

local InsertService = game:GetService("InsertService")
local ServerStorage = game:GetService("ServerStorage")
local Workspace = game:GetService("Workspace")

local GAP_X = 4          -- min gap between models in a row (studs)
local GAP_ROW = 10       -- gap between row strips (so models are >= 10 apart)
local CHEST = 4.5        -- fish/bait centre height above the walkway (R15 chest)
local MARGIN_L, MARGIN_R = 13, 6   -- district side margins (left one holds the row label)
local FRONT, BACK = 10, 6          -- district front/back margins
local DISTRICT_GAP = 24
local TAG_DISTANCE = 60  -- BillboardGui MaxDistance for name tags
local OUTLINE = Color3.fromHex(DATA.outline)
local FONT_TITLE = Font.fromEnum(Enum.Font.LuckiestGuy)
local FONT_BODY = Font.fromEnum(Enum.Font.FredokaOne)

local t0 = os.clock()
local old = Workspace:FindFirstChild("AssetShowcase")
if old then old:Destroy() end

local root = Instance.new("Folder")
root.Name = "AssetShowcase"
local layout = Instance.new("Folder")
layout.Name = "_Layout"
layout.Parent = root

local floorY = 0
local bp = Workspace:FindFirstChild("Baseplate")
if bp and bp:IsA("BasePart") then
	floorY = bp.Position.Y + bp.Size.Y / 2
end

local imports = ServerStorage:FindFirstChild("ShowcaseImports")
local stats = { asset = 0, import = 0, missing = 0 }
local missing, noGlow = {}, {}

local function folder(name, parent)
	local f = parent:FindFirstChild(name)
	if not f then
		f = Instance.new("Folder")
		f.Name = name
		f.Parent = parent
	end
	return f
end

local function part(props, parent)
	local p = Instance.new("Part")
	p.Anchored = true
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	p.Material = Enum.Material.SmoothPlastic
	for k, v in pairs(props) do
		p[k] = v
	end
	p.Parent = parent
	return p
end

local function label(parent, text, font, color, pos, size)
	local l = Instance.new("TextLabel")
	l.BackgroundTransparency = 1
	l.Text = text
	l.FontFace = font
	l.TextColor3 = color
	l.TextStrokeColor3 = OUTLINE
	l.TextStrokeTransparency = 0
	l.TextScaled = true
	l.Position = pos
	l.Size = size
	l.Parent = parent
	return l
end

-- Text on a sign board, on both big faces (Back faces the spawn, +Z).
local function signText(board, text, pps)
	for _, face in ipairs({ Enum.NormalId.Back, Enum.NormalId.Front }) do
		local g = Instance.new("SurfaceGui")
		g.Face = face
		g.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
		g.PixelsPerStud = pps
		g.LightInfluence = 0
		g.Parent = board
		local l = label(g, text, FONT_TITLE, Color3.new(1, 1, 1), UDim2.fromScale(0.04, 0.1), UDim2.fromScale(0.92, 0.8))
		l.TextStrokeTransparency = 0
	end
end

local function nameTag(parent, item, top, x, z)
	local anchor = part({
		Name = item.n .. "_Tag", Size = Vector3.new(0.2, 0.2, 0.2), Transparency = 1,
		CanCollide = false, CanQuery = false, CanTouch = false, Position = Vector3.new(x, top + 1.6, z),
	}, parent)
	local g = Instance.new("BillboardGui")
	g.Size = UDim2.fromOffset(190, 52)
	g.MaxDistance = TAG_DISTANCE
	g.LightInfluence = 0
	g.Parent = anchor
	label(g, item.n, FONT_TITLE, Color3.new(1, 1, 1), UDim2.fromScale(0, 0), UDim2.fromScale(1, 0.6))
	label(g, item.sub, FONT_BODY, Color3.fromHex(item.subColor), UDim2.fromScale(0, 0.6), UDim2.fromScale(1, 0.4))
end

-- Turn whatever LoadAsset / GetObjects / ShowcaseImports gave us into one Model named `name`.
local function wrap(objs, name)
	if #objs == 1 and objs[1]:IsA("Folder") then
		objs = objs[1]:GetChildren()
	end
	local m
	if #objs == 1 and objs[1]:IsA("Model") then
		m = objs[1]
	else
		m = Instance.new("Model")
		for _, o in ipairs(objs) do
			o.Parent = m
		end
	end
	m.Name = name
	m.Parent = nil -- detach from the LoadAsset container before it is destroyed
	return m
end

local function fetch(item)
	if item.id and item.id > 0 then
		local ok, res = pcall(function()
			return InsertService:LoadAsset(item.id)
		end)
		local objs
		if ok and res then
			objs = res:GetChildren()
		else
			local ok2, res2 = pcall(function()
				return game:GetObjects("rbxassetid://" .. item.id)
			end)
			if ok2 and res2 then
				objs = res2
			else
				warn(("[Showcase] %s: could not load asset %d (%s)"):format(item.n, item.id, tostring(res)))
			end
		end
		if objs and #objs > 0 then
			local m = wrap(objs, item.n)
			if res and typeof(res) == "Instance" then
				res:Destroy()
			end
			return m, "asset"
		end
	end
	local src = imports and imports:FindFirstChild(item.n)
	if src then
		return wrap({ src:Clone() }, item.n), "import"
	end
	return nil, "missing"
end

local function aabb(m)
	local h = math.huge
	local x0, y0, z0, x1, y1, z1 = h, h, h, -h, -h, -h
	for _, d in ipairs(m:GetDescendants()) do
		if d:IsA("BasePart") then
			local cf, s = d.CFrame, d.Size / 2
			for _, sx in ipairs({ -1, 1 }) do
				for _, sy in ipairs({ -1, 1 }) do
					for _, sz in ipairs({ -1, 1 }) do
						local p = cf:PointToWorldSpace(Vector3.new(sx * s.X, sy * s.Y, sz * s.Z))
						x0, y0, z0 = math.min(x0, p.X), math.min(y0, p.Y), math.min(z0, p.Z)
						x1, y1, z1 = math.max(x1, p.X), math.max(y1, p.Y), math.max(z1, p.Z)
					end
				end
			end
		end
	end
	return Vector3.new(x0, y0, z0), Vector3.new(x1, y1, z1)
end

local function prepare(item, district)
	local m, how = fetch(item)
	local hasPart = false
	if m then
		for _, d in ipairs(m:GetDescendants()) do
			if d:IsA("BasePart") then
				hasPart = true
				break
			end
		end
	end
	if not hasPart then
		if m then
			m:Destroy()
		end
		how = "missing"
		m = Instance.new("Model")
		m.Name = item.n
		part({ Name = "MissingPlaceholder", Size = Vector3.new(2, 2, 2), Color = Color3.fromRGB(220, 30, 30) }, m)
		m:SetAttribute("Missing", true)
		table.insert(missing, ("%s/%s/%s"):format(district.key, item.g, item.n))
	end
	stats[how] += 1

	local biggest, primary, glowFound = 0, nil, false
	for _, d in ipairs(m:GetDescendants()) do
		if d:IsA("BasePart") then
			d.Anchored = true
			local vol = d.Size.X * d.Size.Y * d.Size.Z
			if d.Name == item.n then
				primary, biggest = d, math.huge
			elseif vol > biggest then
				primary, biggest = d, vol
			end
			if item.glow and d:IsA("MeshPart") and d.Name:lower():find("glow") then
				d.Material = Enum.Material.Neon
				d.Color = Color3.fromHex(item.glow)
				glowFound = true
			end
		end
	end
	m.PrimaryPart = primary
	if item.glow and how ~= "missing" and not glowFound then
		table.insert(noGlow, item.n)
	end

	m:SetAttribute("AssetName", item.n)
	m:SetAttribute("Category", district.key)
	m:SetAttribute("Group", item.g)
	m:SetAttribute("AssetId", item.id or 0)
	m:SetAttribute("SourcePath", item.src)

	if district.yaw ~= 0 and how ~= "missing" then
		local pv = m:GetPivot()
		m:PivotTo(CFrame.new(pv.Position) * CFrame.Angles(0, math.rad(district.yaw), 0) * pv.Rotation)
	end
	item.model = m
	item.min, item.max = aabb(m)
	item.size = item.max - item.min
	local ped = district.pedestal and 1 or 0
	item.slotW = math.max(item.size.X + ped, ped * 2)
	item.slotD = math.max(item.size.Z + ped, ped * 2)
end

local function placeAt(item, x, y, z)
	local c = (item.min + item.max) / 2
	local delta = Vector3.new(x - c.X, y - item.min.Y, z - c.Z)
	item.model:PivotTo(item.model:GetPivot() + delta)
	item.min += delta
	item.max += delta
end

-- 1. Load and measure every model.
local total, done = 0, 0
for _, d in ipairs(DATA.districts) do
	for _, r in ipairs(d.rows) do
		total += #r.items
	end
end
print(("[Showcase] loading %d models..."):format(total))
for _, d in ipairs(DATA.districts) do
	for _, r in ipairs(d.rows) do
		for _, item in ipairs(r.items) do
			prepare(item, d)
			done += 1
			if done % 20 == 0 then
				print(("[Showcase]   %d/%d"):format(done, total))
			end
		end
	end
end

-- 2. Measure districts.
local totalW, maxD = 0, 0
for _, d in ipairs(DATA.districts) do
	local w, depth = 0, FRONT + BACK
	for i, r in ipairs(d.rows) do
		r.w, r.d = 0, 0
		for j, item in ipairs(r.items) do
			r.w += item.slotW + (j > 1 and GAP_X or 0)
			r.d = math.max(r.d, item.slotD)
		end
		w = math.max(w, r.w)
		depth += r.d + 4 + (i > 1 and GAP_ROW or 0)
	end
	d.w, d.d = MARGIN_L + w + MARGIN_R, depth
	totalW += d.w
	maxD = math.max(maxD, depth)
end
totalW += DISTRICT_GAP * (#DATA.districts - 1)

-- 3. Lay out. Districts side by side along X; rows run away from the spawn (-Z).
local zFront = -30
local slabTop = floorY + 0.4
local stripTop = slabTop + 0.2
local x = -totalW / 2
for _, d in ipairs(DATA.districts) do
	local cat = folder(d.key, root)
	local lay = folder(d.key, layout)
	local tags = folder("NameTags", lay)
	local dColor = Color3.fromHex(d.color)
	local cx = x + d.w / 2

	part({ Name = "Floor", Size = Vector3.new(d.w, 0.4, d.d), Color = dColor,
		Position = Vector3.new(cx, floorY + 0.2, zFront - d.d / 2) }, lay)

	-- Big sign on two posts over the district entrance (walk underneath).
	local signW = math.min(d.w - 4, 56)
	local signY = floorY + 18
	local board = part({ Name = "Sign", Size = Vector3.new(signW, 9, 1), Color = dColor,
		Position = Vector3.new(cx, signY, zFront - 1) }, lay)
	signText(board, d.title, 20)
	for _, s in ipairs({ -1, 1 }) do
		part({ Name = "SignPost", Size = Vector3.new(1, signY + 4.5 - floorY, 1), Color = OUTLINE,
			Position = Vector3.new(cx + s * (signW / 2 - 0.5), floorY + (signY + 4.5 - floorY) / 2, zFront - 1) }, lay)
	end

	local z = zFront - FRONT
	for _, r in ipairs(d.rows) do
		local stripD = r.d + 4
		local rz = z - stripD / 2
		local rColor = Color3.fromHex(r.color)
		local rowLay = folder(r.key, lay)
		part({ Name = "RowStrip", Size = Vector3.new(d.w - 2, 0.2, stripD), Color = rColor,
			Position = Vector3.new(cx, slabTop + 0.1, rz) }, rowLay)
		local rl = part({ Name = "RowLabel", Size = Vector3.new(10, 2.6, 0.4), Color = rColor,
			Position = Vector3.new(x + 1 + 5.5, stripTop + 1.6, z - 1) }, rowLay)
		signText(rl, r.label, 30)

		local ix = x + MARGIN_L
		for _, item in ipairs(r.items) do
			local mx = ix + item.slotW / 2
			local base = stripTop
			if d.pedestal then
				local top = math.max(1, CHEST - item.size.Y / 2)
				part({ Name = item.n .. "_Pedestal", Size = Vector3.new(item.slotW, top - 0.25, item.slotD),
					Color = OUTLINE, Position = Vector3.new(mx, stripTop + (top - 0.25) / 2, rz) }, rowLay)
				part({ Name = item.n .. "_PedestalTop", Size = Vector3.new(item.slotW, 0.25, item.slotD),
					Color = rColor, Material = Enum.Material.Neon, Position = Vector3.new(mx, stripTop + top - 0.125, rz) }, rowLay)
				base = stripTop + top + 0.05
			end
			placeAt(item, mx, base, rz)
			item.model.Parent = folder(item.g, cat) -- AssetShowcase/<Category>/<Group>/<Name>
			nameTag(tags, item, item.max.Y, mx, rz)
			ix += item.slotW + GAP_X
		end
		z -= stripD + GAP_ROW
	end
	x += d.w + DISTRICT_GAP
end

local spawn = Instance.new("SpawnLocation")
spawn.Name = "ShowcaseSpawn"
spawn.Anchored = true
spawn.Neutral = true
spawn.Duration = 0
spawn.Size = Vector3.new(10, 1, 10)
spawn.Position = Vector3.new(0, floorY + 0.5, zFront + 22) -- default orientation looks down -Z, at the districts
spawn.TopSurface = Enum.SurfaceType.Smooth
spawn.Parent = layout

root.Parent = Workspace

print(("[Showcase] built %d models in %.1fs: %d from asset IDs, %d from ServerStorage.ShowcaseImports, %d missing")
	:format(total, os.clock() - t0, stats.asset, stats.import, stats.missing))
if #missing > 0 then
	warn("[Showcase] MISSING (red placeholders): " .. table.concat(missing, ", "))
end
if #noGlow > 0 then
	warn("[Showcase] expected a _Glow MeshPart but found none: " .. table.concat(noGlow, ", "))
end
